<?php
namespace App\Http\Controllers\Admin;
use App\Http\Controllers\Controller; use App\Models\Product; use Illuminate\Http\Request; use Inertia\Inertia; use Illuminate\Support\Str;
class ProductController extends Controller { public function index(){return Inertia::render('Admin/Products',['products'=>Product::orderBy('id')->get()]);} public function store(Request $r){$d=$r->validate(['name'=>'required|max:120','description'=>'nullable|max:1000','image'=>'nullable|max:500','price'=>'nullable|numeric|min:0','is_active'=>'boolean']);$d['slug']=Str::slug($d['name']);Product::create($d);return back();} public function update(Request $r,Product $product){$d=$r->validate(['name'=>'required|max:120','description'=>'nullable|max:1000','image'=>'nullable|max:500','price'=>'nullable|numeric|min:0','is_active'=>'boolean']);$d['slug']=Str::slug($d['name']);$product->update($d);return back();} public function destroy(Product $product){$product->update(['is_active'=>false]);return back();} }
